	private static void itemModel2(Item item) {
		MODELS_ITEM.put(key(item), VanillaModels.item2D(item));
	}

	private static void itemModel2(Item item, ModelFile model) {
		MODELS_ITEM.put(key(item), VanillaModels.item2DModel(item, model));
	}

	private static void itemModel2(Item item, String renderType) {
		MODELS_ITEM.put(key(item), VanillaModels.item2D(item, renderType));
	}

	private static void itemSpawnEgg(Item item) {
		MODELS_ITEM.put(key(item), VanillaModels.itemSpawnEgg(item));
	}

	private static void item2DWithBlockTexture(Item item) {
		MODELS_ITEM.put(key(item), VanillaModels.itemWithBlockTexture(item));
	}

	private static void itemGlint(Item item) {
		MODELS_ITEM.put(new ResourceLocation(key(item) + "_base"), VanillaModels.itemGlintBase(item));
		MODELS_ITEM.put(key(item), VanillaModels.itemGlint(item));
	}

	private static void item3D(Block block, ModelFile model) {
		MODELS_ITEM.put(key(block), VanillaModels.item3DModel(block, model));
	}

	private static ResourceLocation key(Item item) {
		return ForgeRegistries.ITEMS.getKey(item);
	}

	private static ResourceLocation key(Block block) {
		ResourceLocation blockLoc = ForgeRegistries.BLOCKS.getKey(block);
		ResourceLocation itemLoc = new ResourceLocation(blockLoc.toString().replace("block/", ""));
		return itemLoc;
	}

	/*
	 * TO BE REMOVED
	 */

	private static ResourceLocation blockTexture(Block block) {
		ResourceLocation name = ForgeRegistries.BLOCKS.getKey(block);
		return new ResourceLocation(name.getNamespace(), ModelProvider.BLOCK_FOLDER + "/" + name.getPath());
	}
